exercises.push(...[["goblet", "Goblet squat", "Bacak", "Ön uyluk ve büyük kalça kası", "Karın ve iç uyluk", "Dambıl", "Dambılı göğsünde tut. Dizlerini bükerek çömel ve doğrul."], ["box", "Sehpaya squat", "Bacak", "Ön uyluk ve büyük kalça kası", "Karın", "Sabit sehpa", "Kalçanı arkadaki sabit sehpaya kontrollü indir. Ayaklarınla zemini iterek kalk."], ["split", "Split squat", "Bacak", "Ön uyluk ve büyük kalça kası", "Arka uyluk", "Vücut ağırlığı", "Ayakların adım pozisyonundayken iki dizini bük. Öndeki ayaktan kuvvet alarak yüksel."], ["splitdb", "Dambıllı split squat", "Bacak", "Ön uyluk ve büyük kalça kası", "Karın", "Dambıl", "Dambılı yanında tut. Adım pozisyonunu koruyarak aşağı in ve kalk."], ["backlunge", "Geri hamle", "Kalça", "Büyük kalça ve ön uyluk", "İç uyluk", "Vücut ağırlığı", "Bir ayağınla geriye adım at ve iki dizini bük. Öndeki ayaktan destek alıp geri gel."], ["rdl", "Romen deadlift", "Kalça", "Arka uyluk ve büyük kalça kası", "Sırt ekstansörleri", "Dambıl", "Dizlerini hafif kır. Dambılı bacağına yakın tutarak kalçanı geriye gönder ve doğrul."], ["morning", "Good morning", "Kalça", "Arka uyluk ve büyük kalça kası", "Sırt ekstansörleri", "Vücut ağırlığı", "Ellerini göğsünde tut. Sırtının biçimini koruyarak kalçadan öne eğil."], ["legext", "Oturarak diz açma", "Bacak", "Ön uyluk", "Kalça fleksörleri", "Sabit sehpa", "Sehpaya otur. Bir dizini açarak alt bacağını kaldırıp kontrollü indir."], ["seatcalf", "Oturarak topuk yükseltme", "Bacak", "Soleus", "Gastroknemius", "Sabit sehpa", "Ayak önünü yerde tut. Otururken topuğunu yükselt ve tekrar indir."], ["kneepush", "Diz üstü şınav", "Göğüs", "Büyük göğüs kası", "Arka kol ve ön omuz", "Mat", "Dizlerin yerdeyken omuzdan dize düz bir çizgi kur. Dirseklerini büküp zemini it."], ["incline", "Eğimli şınav", "Göğüs", "Büyük göğüs kası", "Arka kol ve ön omuz", "Sabit sehpa", "Ellerini sabit bir sehpaya yerleştir. Göğsünü sehpaya yaklaştır ve geri it."], ["floorpress", "Yerde dambıl pres", "Göğüs", "Büyük göğüs kası", "Arka kol ve ön omuz", "Dambıl", "Sırtüstü yat. Üst kolun yere yaklaştığı konumdan dambılı yukarı it."], ["pullover", "Dambıl pullover", "Sırt", "Geniş sırt ve büyük göğüs kası", "Arka kol", "Dambıl", "Sırtüstü yatıp dambılı göğsünün üzerinde tut. Dirsek açını koruyarak başının gerisine indir ve geri getir."], ["skull", "Yatarak triseps açış", "Kol", "Arka kol", "Ön kol", "Dambıl", "Dambılı omzunun üstünde tut. Üst kolunu sabit tutarak dirseğini bük ve aç."], ["overhead", "Baş üstü triseps açış", "Kol", "Arka kol", "Karın", "Dambıl", "Üst kolunu kulağının yanında tut. Dambılı başının arkasına indirip dirseğini aç."], ["front", "Öne kaldırış", "Omuz", "Ön omuz", "Üst göğüs", "Dambıl", "Dambılı uyluğun önünden omuz hizasına kaldır. Gövdeni sallamadan indir."], ["proneY", "Yüzüstü Y kaldırışı", "Sırt", "Alt trapez", "Arka omuz", "Mat", "Yüzüstü uzan. Kolların Y biçimindeyken ellerini zeminden hafifçe kaldır."], ["shrug", "Dambıl omuz silkme", "Sırt", "Üst trapez", "Ön kol", "Dambıl", "Kollarını düz tut. Omuzlarını kulaklarına doğru kaldır ve indir."], ["seatedcurl", "Oturarak pazı bükme", "Kol", "Pazı ve brakiyalis", "Ön kol", "Dambıl", "Sehpada dik otur. Dirseğini gövdenin yanında tutarak dambılı kaldır."], ["seatedpress", "Oturarak omuz presi", "Omuz", "Ön ve orta omuz", "Arka kol", "Dambıl", "Dik otur. Dambılı omuz hizasından başının üzerine it ve geri indir."], ["singlebridge", "Tek bacak kalça köprüsü", "Kalça", "Büyük kalça kası", "Arka uyluk ve karın", "Mat", "Bir ayağını kaldır. Yerdeki topuğundan destek alarak kalçanı yükselt."], ["bridgewalk", "Köprüde diz kaldırma", "Kalça", "Büyük kalça kası", "Karın ve kalça fleksörleri", "Mat", "Köprü pozisyonunda kalçanı sabit tutarak bir dizini kendine çek ve ayağını indir."], ["donkey", "Diz bükülü kalça itişi", "Kalça", "Büyük kalça kası", "Arka uyluk ve karın", "Mat", "Dört ayak üzerinde bir dizini bükülü tut. Ayağını tavana doğru kaldır."], ["bird", "Bird dog", "Karın", "Sırt ekstansörleri ve karın", "Kalça ve omuz", "Mat", "Dört ayak konumundan karşı kol ve bacağını uzat. Gövdeni sabit tutarak geri dön."], ["mount", "Dağ tırmanışı", "Karın", "Kalça fleksörleri ve karın", "Omuz ve ön uyluk", "Mat", "Yüksek plank konumunda sırayla dizlerini göğsüne doğru çek."], ["legraise", "Yatarak bacak kaldırma", "Karın", "Kalça fleksörleri", "Karın", "Mat", "Sırtüstü yat. Gövdeni sabit tutabildiğin aralıkta bacaklarını kaldırıp indir."], ["heel", "Sırtüstü topuk dokundurma", "Karın", "Karın ve kalça fleksörleri", "Oblikler", "Mat", "Sırtüstü yatıp dizlerini bükerek kaldır. Bir topuğunu yere dokundurup başlangıca dön."], ["hipflex", "Ayakta diz çekme", "Bacak", "Kalça fleksörleri", "Karın", "Vücut ağırlığı", "Dik durarak bir dizini kalça hizasına çek. Ayağını kontrollü indir."], ["wallpush", "Duvar şınavı", "Göğüs", "Büyük göğüs kası", "Arka kol ve ön omuz", "Duvar", "Ellerini duvara yerleştir. Dirseklerini bükerek yaklaş ve duvarı it."], ["curlleg", "Ayakta diz bükme", "Bacak", "Arka uyluk", "Baldır", "Vücut ağırlığı", "Dizlerini yan yana tutup bir topuğunu kalçana yaklaştır ve indir."], ["hipback", "Ayakta kalça ekstansiyonu", "Kalça", "Büyük kalça kası", "Arka uyluk", "Vücut ağırlığı", "Gövdeni dik tut. Bir bacağını belinden yaylanmadan geriye uzat."]].map(([id,name,group,primary,secondary,equipment,cue])=>({id,name,group,primary,secondary,equipment,cue})));
Object.assign(media,{"goblet": "data:image/gif;base64,", "box": "data:image/gif;base64,", "split": "data:image/gif;base64,", "splitdb": "data:image/gif;base64,", "backlunge": "data:image/gif;base64,", "rdl": "data:image/gif;base64,", "morning": "data:image/gif;base64,", "legext": "data:image/gif;base64,", "seatcalf": "data:image/gif;base64,", "kneepush": "data:image/gif;base64,", "incline": "data:image/gif;base64,", "floorpress": "data:image/gif;base64,", "pullover": "data:image/gif;base64,", "skull": "data:image/gif;base64,", "overhead": "data:image/gif;base64,", "front": "data:image/gif;base64,", "proneY": "data:image/gif;base64,", "shrug": "data:image/gif;base64,", "seatedcurl": "data:image/gif;base64,", "seatedpress": "data:image/gif;base64,", "singlebridge": "data:image/gif;base64,", "bridgewalk": "data:image/gif;base64,", "donkey": "data:image/gif;base64,", "bird": "data:image/gif;base64,", "mount": "data:image/gif;base64,", "legraise": "data:image/gif;base64,", "heel": "data:image/gif;base64,", "hipflex": "data:image/gif;base64,", "wallpush": "data:image/gif;base64,", "curlleg": "data:image/gif;base64,", "hipback": "data:image/gif;base64,"});
const $=id=>document.getElementById(id);
const byId=id=>exercises.find(e=>e.id===id);
const names=['Pazartesi','Salı','Çarşamba','Perşembe','Cuma','Cumartesi','Pazar'];
const weekdays=['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'];
const newDay=()=>({title:'',note:'',items:[]});
const freshSet=()=>({reps:10,kg:0,done:false});
const copy=value=>JSON.parse(JSON.stringify(value));
const key='bas.weekly.v2';
function localDate(d){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
const weekday=d=>(d.getDay()+6)%7;
function thisWeek(i){const d=new Date();d.setDate(d.getDate()-weekday(d)+i);return localDate(d);}
function dateLabel(k){return new Date(k+'T12:00:00').toLocaleDateString('tr-TR',{day:'numeric',month:'long',year:'numeric'});}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function templateFrom(d){const plan=copy(d);plan.title=plan.title||'';for(const item of plan.items)for(const s of item.sets)s.done=false;return plan;}
function load(){
 const initial={week:Array.from({length:7},newDay),logs:{},favorites:[]};
 try{const now=JSON.parse(localStorage.getItem(key));if(now?.week?.length===7 && now.logs && Array.isArray(now.favorites))return now;
 const old=JSON.parse(localStorage.getItem('bas.studio.v1'));
 if(old?.days){initial.favorites=old.favorites||[];initial.logs=old.days;
 for(const k of Object.keys(old.days).sort()){const i=weekday(new Date(k+'T12:00:00'));if(i>=0&&old.days[k].items?.length)initial.week[i]=templateFrom(old.days[k]);}}
 }catch{}
 return initial;
}
let data=load(), selected=weekday(new Date()), view='plan',sessionDate=thisWeek(selected),activeId,favoritesOnly=false,toastTimer;
function notice(message){$('notice').textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('notice').textContent='',2800);}
function save(){try{localStorage.setItem(key,JSON.stringify(data));}catch{notice('Değişiklik tarayıcıya kaydedilemedi.');}}
const plan=()=>data.week[selected],session=()=>data.logs[sessionDate];
const sets=d=>d.items.flatMap(item=>item.sets);
const done=d=>sets(d).filter(s=>s.done);
const normalize=s=>s.toLocaleLowerCase('tr').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replaceAll('ı','i');
const dayOptions=()=>names.map((n,i)=>i===selected?'':'<option value="'+i+'">'+n+'</option>').join('');
for(const g of new Set(exercises.map(e=>e.group)))$('group').add(new Option(g,g));
for(const e of new Set(exercises.map(e=>e.equipment)))$('equipment').add(new Option(e,e));
function cards(){
 const q=normalize($('search').value.trim());
 const list=exercises.filter(e=>(!$('group').value||e.group===$('group').value)&&(!$('equipment').value||e.equipment===$('equipment').value)&&(!favoritesOnly||data.favorites.includes(e.id))&&normalize([e.name,e.group,e.equipment,e.primary].join(' ')).includes(q));
 $('count').textContent=list.length+' / '+exercises.length;
 $('cards').innerHTML=list.map(e=>{const liked=data.favorites.includes(e.id);return '<article class="card"><button class="tile" data-open="'+e.id+'"><img loading="lazy" alt="" src="'+media[e.id]+'"><span class="caption"><small>'+e.group.toLocaleUpperCase('tr')+'</small><strong>'+e.name+'</strong></span></button><button class="star" data-star="'+e.id+'" aria-label="'+e.name+' favori" aria-pressed="'+liked+'">'+(liked?'★':'☆')+'</button></article>';}).join('')||'<p>Eşleşen hareket bulunamadı.</p>';
}
function openDetail(id){const e=byId(id);activeId=id;$('name').textContent=e.name;$('tag').textContent=e.group+' / '+e.equipment;$('demo').src=media[id];$('demo').alt=e.name+' animasyonu';$('info').innerHTML='<small>ANA KASLAR</small><p>'+e.primary+'</p><small>YARDIMCI KASLAR</small><p>'+e.secondary+'</p><small>UYGULAMA</small><p>'+e.cue+'</p>';$('add').hidden=view!=='plan';$('add').textContent=names[selected]+' planına '+(plan().items.some(i=>i.id===id)?'bir set ekle':'ekle');$('detail').showModal();}
$('cards').onclick=event=>{const btn=event.target.closest('button');if(!btn)return;if(btn.dataset.open)return openDetail(btn.dataset.open);const id=btn.dataset.star;data.favorites=data.favorites.includes(id)?data.favorites.filter(v=>v!==id):[...data.favorites,id];save();cards();};
$('search').oninput=cards;$('group').onchange=cards;$('equipment').onchange=cards;$('fav').onclick=()=>{favoritesOnly=!favoritesOnly;$('fav').setAttribute('aria-pressed',favoritesOnly);$('fav').classList.toggle('on',favoritesOnly);cards();};
$('close').onclick=()=>$('detail').close();
function appendMove(p,id){const existing=p.items.find(item=>item.id===id);if(existing)existing.sets.push(freshSet());else p.items.push({id,sets:Array.from({length:3},freshSet)});}
$('add').onclick=()=>{appendMove(plan(),activeId);save();$('detail').close();render();notice(names[selected]+' planı kaydedildi.');};
function renderWeek(){
 $('week').innerHTML=names.map((name,i)=>{const p=data.week[i],n=p.items.length;return '<button data-day="'+i+'" aria-label="'+name+'" aria-pressed="'+(i===selected)+'" class="'+(i===selected?'on':'')+'"><strong>'+weekdays[i]+'</strong><small>'+esc(p.title||(n?n+' hareket':'Dinlenme'))+'</small><span class="dots"><em style="width:'+Math.min(100,n*16)+'%"></em></span></button>';}).join('');
}
function renderStats(){const progress=Object.values(data.logs).reduce((n,d)=>n+done(d).length,0);
 const weekSets=data.week.reduce((n,d)=>n+sets(d).length,0);
 $('stats').innerHTML=[[data.week.filter(d=>d.items.length).length+' / 7','Antrenman günü'],[weekSets,'Haftalık hedef set'],[progress,'Kaydedilen tamamlanmış set']].map(([v,l])=>'<div class="stat"><strong>'+v+'</strong><span>'+l+'</span></div>').join('');}
function rows(d,training){return d.items.map((it,i)=>'<article class="entry" data-i="'+i+'"><div class="line"><button class="namebtn" data-act="details">'+byId(it.id).name+'</button><div class="toolsrow">'+(training?'':'<button data-act="up" aria-label="Yukarı taşı" '+(i?'':'disabled')+'>↑</button><button data-act="down" aria-label="Aşağı taşı" '+(i===d.items.length-1?'disabled':'')+'>↓</button><button data-act="remove">Kaldır</button>')+'</div></div>'+it.sets.map((s,j)=>'<div class="set '+(training?'':'target')+'" data-j="'+j+'"><small>#'+(j+1)+'</small><label>Tekrar<input required data-field="reps" type="number" min="1" max="999" value="'+s.reps+'"></label><label>Kg<input required data-field="kg" type="number" min="0" max="9999" step=".01" value="'+s.kg+'"></label>'+(training?'<button data-act="done" aria-label="Set tamamlandı" aria-pressed="'+!!s.done+'" class="'+(s.done?'on':'')+'">'+(s.done?'✓':'○')+'</button>':'')+'</div>').join('')+'<div class="actions"><button data-act="more">+ Set</button><button data-act="less" '+(it.sets.length<2?'disabled':'')+'>− Son set</button></div></article>').join('');}
const starters={full:['Tüm vücut',['squat','push','row','bridge']],upper:['Üst vücut',['floorpress','row','press','curl']],lower:['Alt vücut',['goblet','rdl','split','calf']]};
function renderPlan(){const p=plan();$('dayTitle').textContent=names[selected];$('modeLabel').textContent='HAFTALIK ŞABLON';$('intro').textContent='Hedefleri burada düzenle. Yaptığın setleri Antrenman bölümünde işaretle.';
 $('dayContent').innerHTML='<label class="field">Günün adı<input maxlength="60" id="customTitle" placeholder="Örn. Üst vücut" value="'+esc(p.title)+'"></label><button class="primary" data-act="browse" style="margin:10px 0">+ Hareket seç</button>'+ (p.items.length?rows(p,false):'<div class="empty"><b>Bu gün dinlenme günü</b>Kütüphaneden hareket ekle veya hazır bir gün seç.</div>')+'<label class="field">Plan notu<textarea class="note" id="dayNote" rows="2" placeholder="Her hafta hatırlamak istediklerin">'+esc(p.note)+'</textarea></label><div class="planfoot"><div class="actions"><select id="starter" aria-label="Hazır gün"><option value="full">Tüm vücut</option><option value="upper">Üst vücut</option><option value="lower">Alt vücut</option></select><button data-act="starter">Hazır günü uygula</button></div><div class="actions"><select id="copyTo" aria-label="Kopyalanacak gün">'+dayOptions()+'</select><button data-act="copy">Günü kopyala</button></div></div>';}
function renderSession(){const d=session();$('dayTitle').textContent=d?.title||names[selected];$('modeLabel').textContent='ANTRENMAN KAYDI';$('intro').textContent=dateLabel(sessionDate);
 if(!d){$('dayContent').innerHTML=plan().items.length?'<p>'+plan().items.length+' hareket · '+sets(plan()).length+' hedef set</p><button class="primary" data-act="start">Antrenmanı başlat</button>':'<div class="empty"><b>Bugün için hareket planlanmamış.</b><button data-act="edit">Günün planını düzenle</button></div>';return;}
 $('dayContent').innerHTML='<div class="line"><small id="summary">'+done(d).length+' / '+sets(d).length+' SET TAMAMLANDI</small></div>'+rows(d,true)+'<label class="field">Antrenman notu<textarea class="note" id="dayNote" placeholder="Bu seansa özel not">'+esc(d.note)+'</textarea></label>';}
function renderHistory(){const p=$('history');p.innerHTML='<h2>Antrenman geçmişi</h2>';const keys=Object.keys(data.logs).sort().reverse();if(!keys.length)p.insertAdjacentHTML('beforeend','<p>Başlattığın antrenmanlar ve tamamladığın setler burada görünecek.</p>');for(const k of keys){const d=data.logs[k],completed=done(d);const volume=completed.reduce((n,s)=>n+s.reps*s.kg,0);p.insertAdjacentHTML('beforeend','<div class="historyrow"><div><b>'+dateLabel(k)+'</b><p>'+esc(d.title||'Antrenman')+'</p><small>'+completed.length+'/'+sets(d).length+' set · '+volume.toLocaleString('tr-TR')+' kg hacim</small></div><button data-log="'+k+'">Kaydı aç</button></div>');}}
function render(){const training=view==='session',history=view==='history';$('title').textContent={plan:'Haftalık planım',session:'Antrenmanım',history:'Antrenman geçmişi'}[view];document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('on',b.dataset.view===view));
 $('weekPanel').hidden=history||(training&&sessionDate!==thisWeek(selected));$('weekLabel').textContent=training?'Bu haftanın seansları':'Hafta düzeni';$('weekMeta').textContent=training?dateLabel(thisWeek(0))+' haftası':'Her hafta tekrarlanır';$('layout').hidden=history;$('layout').classList.toggle('focus',training);$('history').hidden=!history;$('library').hidden=view!=='plan';$('timerWrap').hidden=!training;renderWeek();renderStats();if(history)renderHistory();else if(training)renderSession();else renderPlan();}
document.querySelector('nav').onclick=e=>{const b=e.target.closest('[data-view]');if(!b)return;view=b.dataset.view;sessionDate=thisWeek(selected);render();};
$('week').onclick=e=>{const b=e.target.closest('[data-day]');if(b){selected=Number(b.dataset.day);sessionDate=thisWeek(selected);render();}};
$('history').onclick=e=>{const k=e.target.closest('[data-log]')?.dataset.log;if(k){sessionDate=k;selected=weekday(new Date(k+'T12:00:00'));view='session';render();}};
$('dayContent').oninput=e=>{if(e.target.id==='customTitle'){plan().title=e.target.value;save();renderWeek();}if(e.target.id==='dayNote'){(view==='plan'?plan():session()).note=e.target.value;save();}};
$('dayContent').onchange=e=>{const el=e.target;if(!el.dataset.field)return;const d=view==='plan'?plan():session();const s=d.items[+el.closest('.entry').dataset.i].sets[+el.closest('.set').dataset.j];if(!el.validity.valid){el.value=s[el.dataset.field];notice('Geçerli bir sayı gir.');return;}s[el.dataset.field]=el.valueAsNumber;save();};
$('dayContent').onclick=e=>{const b=e.target.closest('[data-act]');if(!b)return;const act=b.dataset.act;const training=view==='session';let d=training?session():plan();
 if(act==='browse'){$('library').scrollIntoView({block:'start'});$('search').focus({preventScroll:true});return;}
 if(act==='start'){data.logs[sessionDate]=templateFrom(plan());}
 else if(act==='edit'){view='plan';}
 else if(act==='copy'){const target=Number($('copyTo').value),p=data.week[target];if((p.items.length||p.title||p.note)&&!confirm(names[target]+' planının üzerine yazılsın mı?'))return;data.week[target]=templateFrom(plan());notice(names[target]+' gününe kopyalandı.');}
 else if(act==='starter'){if((d.items.length||d.title||d.note)&&!confirm('Bu gün hazır planla değiştirilsin mi?'))return;const [title,ids]=starters[$('starter').value];const p=newDay();p.title=title;ids.forEach(id=>appendMove(p,id));data.week[selected]=p;}
 else {const i=+b.closest('.entry').dataset.i,item=d.items[i];if(act==='details')return openDetail(item.id);
 if(act==='remove'){if(!confirm(byId(item.id).name+' plandan kaldırılsın mı?'))return;d.items.splice(i,1);}
 if(act==='up'&&i>0)[d.items[i-1],d.items[i]]=[item,d.items[i-1]];
 if(act==='down'&&i<d.items.length-1)[d.items[i+1],d.items[i]]=[item,d.items[i+1]];
 if(act==='more')item.sets.push({...item.sets.at(-1),done:false});
 if(act==='less'&&item.sets.length>1){if(item.sets.at(-1).done&&!confirm('Tamamlanan son set silinsin mi?'))return;item.sets.pop();}
 if(act==='done'){const s=item.sets[+b.closest('.set').dataset.j];s.done=!s.done;}}
 save();render();
};
let remaining=60,deadline=0,interval;
function tick(){if(deadline)remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));$('clock').textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0');if(deadline&&!remaining){clearInterval(interval);deadline=0;notice('Dinlenme süresi doldu.');}$('timerBtn').textContent=deadline?'Duraklat':'Başlat';}
function reset(){clearInterval(interval);deadline=0;remaining=Number($('duration').value);tick();}
$('duration').onchange=reset;$('reset').onclick=reset;$('timerBtn').onclick=()=>{if(deadline){tick();clearInterval(interval);deadline=0;}else{if(!remaining)remaining=Number($('duration').value);deadline=Date.now()+remaining*1000;interval=setInterval(tick,200);}tick();};
cards();render();
